        StyleManager.shared.objectWillChange.send()
        StyleManager.shared.userStyles.styles.append(style)
        notice = AppNotice(
            title: "Style Saved",
            message: "\"\(style.name)\" was added to User Styles."
        )
    }

    public func applyStyle(_ style: Style) {
