    public func copyAdjustmentsForTool(_ toolID: String) {
        guard let style = snapshotCurrentAdjustments(name: "\(toolID) Copy") else {
            notice = AppNotice(
                title: "Nothing to Copy",
                message: "Select an image before copying \(toolID) adjustments."
