        Button(action: action) {
            Image(systemName: systemName)
                .font(.system(size: 11))
                .frame(width: 18, height: 18)
        }
        .buttonStyle(.plain)
        .foregroundColor(CaptureOneTheme.Colors.textPrimary)
    }
