        case .keyboardShortcuts:
            ShortcutEditorSheet()
        case .sessionUpgrade:
            if let session = commands.session {
                SessionUpgradeDialog(
                    session: session,
                    onUpgrade: {
                        commands.performUpgrade()
                        commands.presentedSheet = nil
                    },
